import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Remote storage (S3)","description":"MinIO / R2 / AWS S3: public bucket, private bucket, public_base_url, cluster plus Redis.","frontmatter":{"title":"Remote storage (S3)","description":"MinIO / R2 / AWS S3: public bucket, private bucket, public_base_url, cluster plus Redis."},"headers":[],"relativePath":"en/guide/config/s3.md","filePath":"en/guide/config/s3.md","lastUpdated":1790057721000}`),a={name:`en/guide/config/s3.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="remote-storage-s3" tabindex="-1">Remote storage (S3) <a class="header-anchor" href="#remote-storage-s3" aria-label="Permalink to “Remote storage (S3)”">​</a></h1><p>Use object storage for large packages or CDN. For a single disk, see <a href="./local-storage">local storage</a>.</p><p>Compatible with MinIO, Cloudflare R2, and AWS S3. Set <code>storage.driver: s3</code>.</p><h2 id="public-bucket-storage-s3" tabindex="-1">Public bucket <code>storage.s3</code> <a class="header-anchor" href="#public-bucket-storage-s3" aria-label="Permalink to “Public bucket storage.s3”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Meaning</th><th>When to change</th></tr></thead><tbody><tr><td><code>endpoint</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>API endpoint</td><td>Required for MinIO/R2; AWS may use the default</td></tr><tr><td><code>region</code></td><td>string</td><td><code>auto</code></td><td>Region</td><td>Real AWS region; R2 can keep <code>auto</code></td></tr><tr><td><code>bucket</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Public artifact bucket</td><td>Required when <code>driver=s3</code></td></tr><tr><td><code>access_key</code> / <code>secret_key</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Credentials</td><td>Minimum: Put/Get public objects; inject via env</td></tr><tr><td><code>use_path_style</code></td><td>bool</td><td><code>true</code></td><td>Path-style URLs</td><td>Virtual-hosted AWS can set false</td></tr><tr><td><code>public_base_url</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>External download root; empty builds anonymous GET from endpoint+bucket</td><td>Point at the CDN origin</td></tr></tbody></table><p>Env: <code>KIRIVERS_STORAGE_S3_*</code>, <code>KIRIVERS_STORAGE_S3_PUBLIC_BASE_URL</code>.</p><h2 id="private-bucket-storage-private" tabindex="-1">Private bucket <code>storage.private</code> <a class="header-anchor" href="#private-bucket-storage-private" aria-label="Permalink to “Private bucket storage.private”">​</a></h2><p>GeoIP MMDB and similar. If <code>driver=s3</code> and the private bucket is empty, GeoIP upload fails and <strong>must not</strong> write the public bucket. Env: <code>KIRIVERS_STORAGE_PRIVATE_*</code>.</p><p>Do not mix installers and GeoIP in one bucket.</p><h2 id="multi-node-downloads" tabindex="-1">Multi-node downloads <a class="header-anchor" href="#multi-node-downloads" aria-label="Permalink to “Multi-node downloads”">​</a></h2><p>Requires <code>storage.driver=s3</code> and <code>cache.driver=redis</code>. See <a href="./cluster">cluster</a>.</p><ul><li><code>cluster.download: s3</code>: check returns public object URLs (CDN-capable).</li><li><code>cluster.download: local</code>: app nodes proxy bytes; check uses <code>private, no-store</code>.</li></ul><p>On failure, read process storage logs (<code>mod=storage</code>).</p><p>Project PATCH currently <strong>rejects</strong> <code>storage_visibility=private</code>. Signed URLs still apply on local-proxy paths. See <a href="/en/guide/features/cdn">CDN and downloads</a>.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};